code.python:
class Solution:
    def cubeRoot(self, volume: float) -> float:
        bound = max(1.0, abs(volume))
        lo, hi = -bound, bound
        for _ in range(200):
            mid = (lo + hi) / 2
            if mid * mid * mid < volume:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2

